fn solve(a: i8, b: i8) -> (i8, i8) {
    // The number of different‐type days is just the smaller of the two counts.
    let different = a.min(b);

    // Compute the absolute difference, then integer‐divide by 2 for same‐type days.
    let diff = (a - b).abs();
    let same = diff / 2;

    (different, same)
}

